const fixtureReplacements: ReadonlyArray<readonly [string, string]> = [
  ["桃", "peach"],
  ["李", "plum"],
  ["阿青", "Alex"],
  ["过关", "Pass"],
  ["很稳", "Strong performance"],
  ["再试一次", "Try again"],
  ["松", "pine"],
  ["长安", "☀☂"],
  ["春风", "★☆"],
  ["小城", "Small Town"],
  ["中文字符数", "Unicode character count"],
  ["返回值：", "Return value: "],
  ["你好，", "Hello, "],
  ["小满", "Xiaoman"],
  ["用法：hello_cli 名字", "Usage: hello_cli NAME"],
  ["又一程", "sky"],
];

function translateFixture(value: string): string {
  return fixtureReplacements.reduce((text, [source, replacement]) => text.split(source).join(replacement), value);
}

const sourceNotebooks = [...scratchNotebooks, ...foundationNotebooks, ...intermediateNotebooks, ...projectNotebooks];
const sourceSlugs = new Set(sourceNotebooks.map((notebook) => notebook.slug));
for (const slug of Object.keys(translations)) {
  if (!sourceSlugs.has(slug)) throw new Error(`Unknown English notebook translation: ${slug}`);
}

export const elixirNotebooksEn: NotebookLesson[] = sourceNotebooks.map((notebook) => {
  const translation = translations[notebook.slug];
  if (!translation) throw new Error(`Missing English notebook translation: ${notebook.slug}`);
  if (!notebook.review) throw new Error(`Missing review for English notebook: ${notebook.slug}`);
  if (translation.notes.length !== notebook.notes.length || translation.trace.length !== notebook.trace.length || translation.exercise.choices.length !== notebook.exercise.choices.length) {
    throw new Error(`English notebook translation count mismatch: ${notebook.slug}`);
  }
  const translated: NotebookLesson = {
    ...notebook,
    ...translation,
    code: translateFixture(notebook.code),
    notes: notebook.notes.map((note, index) => ({ ...note, ...translation.notes[index] })),
    trace: notebook.trace.map((step, index) => ({ ...step, ...translation.trace[index], output: translateFixture(step.output) })),
    exercise: { ...notebook.exercise, ...translation.exercise, code: translateFixture(notebook.exercise.code), output: translateFixture(notebook.exercise.output) },
    review: { ...notebook.review, ...translation.review },
  };
  if (/\p{Script=Han}/u.test(JSON.stringify(translated))) throw new Error(`Untranslated Chinese in English notebook: ${notebook.slug}`);
  return translated;
});
